from typing import List

class Solution:
    def isPossibleToSplit(self, nums: List[int]) -> bool:
        seen = set()
        counts = {}
        for num in nums:
            counts[num] = counts.get(num, 0) + 1
            if counts[num] > 2:
                return False
        return True
